// A font file imported by a module is the number Metro gives the asset.
declare module '*.otf' {
  const source: number;
  export default source;
}

// A picture imported by a module is an image source.
declare module '*.png' {
  const source: number;
  export default source;
}

declare module '*.jpg' {
  const source: number;
  export default source;
}
